import { useEffect, useState, useCallback } from 'react';
import { Bell, AlertTriangle, Info, AlertCircle } from 'lucide-react';
import api from '../lib/apiClient.js';

const ICONS = {
  CRITICAL: { Icon: AlertTriangle, tone: 'text-red-600' },
  WARNING: { Icon: AlertCircle, tone: 'text-amber-600' },
  NOTICE: { Icon: Info, tone: 'text-blue-600' },
  INFO: { Icon: Info, tone: 'text-ink-muted' },
};

/**
 * Notification bell.
 *
 * Polls rather than holding a socket open: alerts here are generated by nightly
 * jobs, so a 60-second delay is irrelevant and a websocket would be
 * infrastructure earning nothing.
 */
export default function NotificationBell() {
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState([]);
  const [unread, setUnread] = useState(0);

  const load = useCallback(async () => {
    try {
      const res = await api.get('/notifications', { params: { limit: 10 } });
      setItems(res.data.data);
      setUnread(res.data.meta.unread);
    } catch {
      // A failing notification poll must never disrupt the page the user is on.
    }
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, 60_000);
    return () => clearInterval(id);
  }, [load]);

  const markAll = async () => {
    await api.post('/notifications/read-all').catch(() => {});
    load();
  };

  return (
    <div className="relative">
      <button
        onClick={() => setOpen((v) => !v)}
        className="relative rounded-control border border-line-strong p-1.5 text-ink-soft hover:bg-paper"
        aria-label={`Notifications${unread ? `, ${unread} unread` : ''}`}
      >
        <Bell className="h-4 w-4" />
        {unread > 0 && (
          <span className="absolute -right-1 -top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-red-600 px-1 text-[10px] font-medium text-white">
            {unread > 9 ? '9+' : unread}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 z-20 mt-2 w-80 rounded-panel border border-line bg-surface shadow-lg">
          <div className="flex items-center justify-between border-b border-line px-4 py-2">
            <p className="text-sm font-medium text-ink">Notifications</p>
            {unread > 0 && (
              <button onClick={markAll} className="text-xs text-ink-muted hover:text-ink">
                Mark all read
              </button>
            )}
          </div>

          <div className="max-h-80 overflow-y-auto">
            {items.length === 0 && (
              <p className="px-4 py-8 text-center text-sm text-ink-muted">Nothing to report</p>
            )}

            {items.map((n) => {
              const { Icon, tone } = ICONS[n.severity] ?? ICONS.INFO;
              return (
                <div
                  key={n.id}
                  className={`flex gap-2.5 border-b border-slate-100 px-4 py-3 ${n.read ? 'opacity-60' : ''}`}
                >
                  <Icon className={`mt-0.5 h-4 w-4 shrink-0 ${tone}`} />
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-ink">{n.title}</p>
                    {n.body && <p className="mt-0.5 text-xs text-ink-soft">{n.body}</p>}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
